from pathlib import Path
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,Image
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.colors import HexColor,white
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
out=Path('output/pdf');out.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='BodySmall',fontName='Helvetica',fontSize=9,leading=13,textColor=HexColor('#243247'),spaceAfter=7))
styles.add(ParagraphStyle(name='TitleCustom',fontName='Helvetica-Bold',fontSize=25,leading=29,textColor=HexColor('#162a40'),spaceAfter=17))
styles.add(ParagraphStyle(name='SectionCustom',fontName='Helvetica-Bold',fontSize=14,leading=18,textColor=HexColor('#126f85'),spaceBefore=12,spaceAfter=8))
styles.add(ParagraphStyle(name='Cell',fontName='Helvetica',fontSize=8,leading=11))
story=[]
def p(text):story.append(Paragraph(text,styles['BodySmall']))
def title(num,text):p('BYTEENGINE / MODULAR WEAPON GAMEPLAY 2.1 / '+str(num));story.append(Paragraph(text,styles['TitleCustom']))
def h(text):story.append(Paragraph(text,styles['SectionCustom']))
def table(rows,widths=[150,355]):
 t=Table([[Paragraph(str(c),styles['Cell']) for c in r] for r in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),HexColor('#e0edf1')),('ROWBACKGROUNDS',(0,1),(-1,-1),[white,HexColor('#f2f5f8')]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,0),(-1,0),.7,HexColor('#126f85'))]));story.append(t)
def page():story.append(PageBreak())
title(1,'Where the settings live')
p('The old Gun Lab used three hard-coded weapons and unlimited refill behavior. Version 2.1 replaces those fixed cases with generic weapon definitions and separate instance ammunition. The four demo slots include two different pistols.')
h('Plugin or built-in?')
p('<b>Weapon Equipment, Weapon Definition and Weapon Instance are plugin components.</b> Their canonical source remains under the engine repository, Plugins/KarlsonDemo. The package keeps its existing identifier, bytebard.karlsondemo, so old event IDs can remain loadable. The package display name is Modular Weapon Gameplay.')
p('Built-in engine systems provide the FPS camera, character movement, collision queries, health, projectile simulation, model importer, skeletal renderer, animation profiles, event sheets and Blueprint serialization. The plugin composes these systems; weapon-specific rules are not baked into the camera or character motor.')
h('Edit an existing weapon')
p('1. Open Documents/karlson demo/karlson demo.byteproject.<br/>2. Expand FPS Character, then FPS Camera, and select a weapon view model.<br/>3. In <b>Weapon Definition</b>, edit capacity, shot mode, rate, damage, spread, reload timing or presentation.<br/>4. In <b>Weapon Instance</b>, edit <b>Current Ammo</b> and <b>Reserve Ammo</b>.<br/>5. Open Assets/Events/FPS controls.byteevents. Equip weapon slot has editable Target and Slot arguments. More actions are in the <b>Weapons</b> category.')
h('Try the four variants')
table([['Key / slot','Demo configuration'],['1 / 0','Pistol: 12-round magazine, 60 reserve, 25 damage, 270 RPM, hitscan.'],['2 / 1','Shotgun: 6 shells, 30 reserve, eight pellets at 12 damage each, 6-degree cone, per-round loading.'],['3 / 2','Rifle: 24 rounds, 60 reserve, 18 damage, 550 RPM, automatic hitscan.'],['4 / 3','Heavy pistol: same pistol model, independent 8-round magazine, 60 reserve, 65 damage, 160 RPM, physical projectile at 22 m/s.']])
p('WASD moves, mouse looks, Space jumps, left mouse fires, R reloads. Click Game View after Play to capture input. Reopen the project if an editor session still has plugin version 1.0 loaded.')
page();title(2,'Authorable weapon settings')
p('Definition values are saved on each weapon object or native weapon Blueprint. Instance values are saved separately. Duplicating a Blueprint creates a new variant; changing one scene instance does not globally change every other instance.')
table([['Setting','Meaning / behavior'],['Display Name / Slot','HUD label and zero-based equipment slot. Slots can extend beyond the four demo weapons; keep them unique within one inventory.'],['Shot Mode / Trigger Mode','Hitscan or Projectile; SemiAutomatic or Automatic. Types such as pistol do not choose behavior implicitly.'],['Magazine Capacity / Current Ammo','Maximum rounds held versus remaining rounds. Ammo operations clamp current ammo to capacity.'],['Reserve Capacity / Reserve Ammo','Maximum carried reserve versus actual reserve. Reload transfers available reserve; it does not create rounds.'],['Ammo Per Shot / Infinite Reserve','Cost per trigger activation, independent of pellet count. Infinite reserve skips reserve consumption, but still reloads the magazine.'],['Rounds Per Minute','Controls shot cooldown. Runtime clamps 1-3000 RPM. Equip delay and reload also block firing.'],['Damage Per Pellet / Pellets Per Shot','Each ray/projectile carries configured damage. Pellet count is bounded to 1-32.'],['Spread Degrees / Random Seed','Uniform sampling across a cone disk; zero spread aims straight. Per-instance seed makes repeatable tests possible.'],['Range / Hit Mask Bits / Hit Impulse','Hitscan and aim-query distance, included collision layers and impact impulse. -1 mask includes all layers; owner is excluded.'],['Reload Mode / Reload Seconds','Magazine transfers missing rounds atomically at completion. PerRound transfers one round per cycle and repeats until full or reserve empty.'],['Equip Seconds','Delay before a newly equipped weapon can fire. Switching cancels unfinished reload and retains existing ammo.'],['Projectile Speed / Lifetime','Native swept collision projectile movement, metres per second and seconds. Lifetime bounds cleanup.'],['Projectile Blueprint','Optional visual/gameplay Blueprint. An empty reference uses the built-in visible projectile sphere.'],['Max Active Projectiles','Per-owner live projectile budget, bounded to 1-512. A shot exceeding budget is rejected without consuming ammunition.'],['Muzzle Source / Socket / Bone / Local Offset','Automatic: animation-workspace socket first, imported bone second, weapon-local offset last. AnimationSocket uses your authored socket name; ModelBone uses any chosen bone; LocalOffset needs no muzzle bone. Both projectile launch and visible traces use the result.'],['Fire / Reload / Equip Animation','Named actions on the weapon Animation Controller profile. Clips are not hard-coded by gun type.'],['Show Shot Trace / Trace Seconds / Trace Width / Show Camera Aim Ray','Optional debug presentation. Gold is hitscan muzzle tracer; cyan is projectile aim tracer; optional red is the camera query ray. Debug lines intentionally draw through walls and expire.']])
page();title(3,'Event sheet controls')
p('Each action has an editable equipment Target: Self, an object name, or id:GUID. Target should point to the object carrying Weapon Equipment, not the view model. Actions act on the selected weapon.')
table([['Action','Editable arguments / use'],['Equip weapon slot','Target, Slot. Use number-key conditions or your own inventory UI.'],['Fire / Reload / Cancel reload','Target. Fire honors cooldown, ammo and reload state.'],['Set magazine and reserve ammo','Target, Current magazine ammo, Reserve ammo. Cancels reload and clamps values.'],['Add reserve ammo','Target, Ammo amount. Positive for pickups; negative for removal.'],['Set magazine capacity','Target, Magazine capacity. Immediately clamps remaining ammo.'],['Use projectile / hitscan mode','Target, Projectile boolean. Off means hitscan.'],['Set damage, fire rate and spread','Target, Damage per pellet, Rounds per minute, Spread cone degrees, Pellets per shot.'],['Show shot traces','Target, Enabled, Trace duration seconds. Width remains authorable on Definition.'],['Use built-in fire input','Target, Enabled. Turn off when your event sheet supplies all firing input.'],['Copy ammo to object variables','Target, Magazine variable name, Reserve variable name. Feed custom HUD/event logic.']])
h('Conditions and notifications')
p('Equipped weapon can fire; equipped weapon is reloading; magazine ammo is at least Amount; weapon Slot is equipped; weapon fired this frame; hitscan hit this frame; reload completed this frame. Frame notifications are evaluated after equipment update. The hit notification currently covers hitscan; projectile impacts use native Health/Projectile behavior.')
h('Use an animation-profile socket')
p('Open the weapon animation profile, choose Sockets, select a frame/barrel bone and add a socket at the muzzle. Set Weapon Definition Muzzle Source to AnimationSocket and Muzzle Socket to its name. The demo now includes WeaponMuzzle sockets attached to Frame. The workspace saves sockets as model metadata, so variants sharing a model can reuse them. No bone named MuzzleSocket is required.')
h('Make another pistol')
p('Duplicate Assets/Blueprints/Pistol.byteblueprint, rename it, and place the weapon under the configured inventory root. Give Weapon Definition a unique Slot. Set capacity/rate/damage/shot mode as desired; set Weapon Instance current and reserve ammo. Reuse or replace the model and animation profile. Add an Equip weapon slot event with that Slot. The component does not require a specific object name.')
p('The demo uses optional built-in left-mouse firing, with switching and reload authored in the event sheet. An event-only setup turns built-in firing off, then uses a mouse condition plus Fire action. Holding a condition fires whenever CanFire permits; use a pressed condition for a semi-automatic input flow.')
h('Timing and cancellation')
p('Ammo commits when the configured reload timer finishes. Match Reload Seconds to the imported action duration if you edit either. This version does not yet use a clip marker as the authoritative ammo-commit signal. Switching cancels the current reload; rounds already inserted by a per-round cycle stay in the weapon.')
page();title(4,'Research and plugin design')
p('These are design recommendations derived from primary engine documentation and this engine implementation, not a claim that ByteEngine implements Unreal or Unity APIs.')
h('Separate tuning, state and equipment')
p('Epic Lyra documents definitions, inventory instances, equipment definitions and equipped instances as different responsibilities. It explicitly permits duplicate item instances and keeps ammunition with inventory state. Applied here: weapon tuning lives in Definition, ammunition in Instance, and selection/input in Equipment. A second pistol is a data variant, not a new switch statement. [1]')
p('Unity documents ScriptableObject assets as a way to hold shared authoring data independently of instances. That supports separating configuration from mutable state. ByteEngine currently uses native Blueprints for editable weapon variants: definitions are copied per instance rather than loaded as one shared immutable weapon-profile asset. A dedicated shared profile editor/cache is a future extension, not implemented here. [2]')
h('Keep dependencies narrow')
p('Epic modular game features are designed to isolate features and reduce accidental dependencies. Its guidance minimizes interaction with project-specific actor classes. Applied here: the plugin binds camera, inventory root and optional status text by ID; it discovers weapons by component; it has no required pistol/shotgun/rifle object names. It reuses engine rendering and collision. [3]')
table([['Consideration','Current implementation / next boundary'],['Authoring contract','Native scalar, enum, reference and ammo properties; parameterized actions and conditions; Blueprint variants. Inspector and event metadata validated.'],['Runtime rules','Finite reserves, bounded spread/rate, cooldown, reload cancellation, independent swap state, owner exclusion and projectile cleanup.'],['Presentation','Generic imported rigs, stable root plus WeaponMotion, configured named actions and muzzle socket. Optional HUD binding and bounded debug traces.'],['Serialization / packaging','Plugin v2.1, retained ID and legacy select actions. New project authored with the new components. Older scenes need weapon definitions/instances attached; old hard-coded ammo arrays are not migrated automatically.'],['Scope boundaries','Local single-player foundation. No replication, save-game adapter, attachment system, pooling, ballistic gravity, explosions, ADS or separate empty/tactical reload clips yet. Add these as explicit modules when required.']])
h('Primary sources')
for label,url in [('1. Epic - Lyra inventory and equipment','https://dev.epicgames.com/documentation/en-us/unreal-engine/lyra-inventory-and-equipment-in-unreal-engine'),('2. Unity - ScriptableObject','https://docs.unity3d.com/6000.1/Documentation/Manual/class-ScriptableObject.html'),('3. Epic - Game features and modular gameplay','https://dev.epicgames.com/documentation/unreal-engine/game-features-and-modular-gameplay-in-unreal-engine')]:p('<link href="'+url+'" color="#126f85">'+label+'</link>')
page();title(5,'Assets and verification')
p('The supplied Vehicle Survivors Blender MCP add-on was inspected, installed and used through its localhost socket operations. It is a local bridge, rather than a registered native MCP tool in this session. The original Blender file remains preserved; the revision is saved separately.')
table([['Model','Revision geometry / rig'],['Pistol','2,268 triangles; 9 bones. Separate frame, slide, magazine, trigger, muzzle socket, motion root and hands.'],['Shotgun','2,240 triangles; 10 bones. Separate pump, loading gate, shell prop, trigger, muzzle socket, motion root and hands.'],['Rifle','3,460 triangles; 9 bones. Separate magazine, bolt, trigger, muzzle socket, motion root and hands.']])
p('Each GLB contains one weapon skin and Idle, Fire, Reload and Equip clips. Parts are rigidly weighted; detail meshes merge only within a material/motion assembly. Total source geometry is 7,968 triangles including hands. FPS framing, detached magazines and loading poses are reviewed in addition to studio silhouettes.')
h('Saved files')
p('<b>Project:</b> C:/Users/codex/Documents/karlson demo<br/><b>Revised Blender source and GLBs:</b> C:/Users/codex/Downloads/byte engine files/Karlson V2<br/><b>Plugin source:</b> C:/Users/codex/ByteEngine/Plugins/KarlsonDemo<br/><b>Model review images:</b> Karlson V2/Previews<br/><b>Native screenshots and test records:</b> project Preview folder')
h('Validation coverage')
p('Design checks cover serialization, different pistol definitions, inspector-editable ammo/settings, action arguments, capacity clamping, empty/infinite reserves, cancellation and single-weapon exports. Native gameplay checks cover imported bone animation, pellet/automatic fire, reserve transfer, swap persistence, projectile spawn/impact, trace expiry, movement, look, jump and floor contact. The real editor Play path is also checked using the packaged plugin.')
h('Animation scope')
p('These are original stylized props and simple gloved hand assemblies, with artistic proportions. The magazine is withdrawn and carried below the view before reappearing; it is reused as the incoming magazine. This is a compact game animation rather than a complete character inventory handoff. The hands use rigid assemblies, not individually articulated finger rigs. Sound, muzzle effects and separate empty-reload handling remain separate work.')
p('Debug shot traces are diagnostic geometry, not a shipping muzzle-flash effect. Gold/cyan muzzle tracers explain visible shots; the optional red camera ray shows the actual aiming query. Projectile movement uses native swept sphere collision and currently travels without gravity.')
def footer(canvas,doc):
 canvas.setStrokeColor(HexColor('#d4dee6'));canvas.line(45,42,550,42);canvas.setFont('Helvetica',8);canvas.setFillColor(HexColor('#617186'));canvas.drawString(45,28,'Karlson demo | Weapon authoring guide | 12 October 2026');canvas.drawRightString(550,28,str(doc.page))
SimpleDocTemplate(str(out/'Weapon Gameplay - Settings and Design.pdf'),pagesize=A4,rightMargin=45,leftMargin=45,topMargin=40,bottomMargin=55).build(story,onFirstPage=footer,onLaterPages=footer)
